import { h } from "@stencil/core";
import {
	createDOMElementFromVNode,
	debounce,
} from "../../utils/function-helper";
import { sanitizeHtml } from "../../utils/sanitizeHtml";

const browserDownloadCsv = (resultCsv, filename) => {
	const blob = new Blob([resultCsv], { type: "text/csv" });
	const link = document.createElement("a");
	link.href = URL.createObjectURL(blob);
	link.download = filename;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
};

const showChartPopover = async (
	tooltipRef: HTMLHbrPopoverElement,
	data,
	event: MouseEvent,
	customItemTooltip:
		| false
		| ((data, event: MouseEvent, h) => string | object | false),
	defaultTooltipGenerator: (data, event) => string | object | false,
) => {
	if (!tooltipRef) {
		console.warn("Tooltip reference is not provided");
		return;
	}

	// Explicitly disabled
	if (customItemTooltip === false) {
		tooltipRef.open = false;
		return;
	}

	const target = event.target as HTMLElement | null;
	if (!target) {
		tooltipRef.open = false;
		return;
	}

	const content = tooltipRef.querySelector(
		"[slot=content]",
	) as HTMLDivElement | null;
	if (!content) {
		console.warn("Tooltip content element not found: [slot=content]");
		return;
	}

	// 1) Try custom tooltip (if provided)
	const custom =
		typeof customItemTooltip === "function"
			? customItemTooltip(data, event, h)
			: undefined;

	// Custom tooltip can explicitly disable
	if (custom === false) {
		tooltipRef.open = false;
		return;
	}

	// 2) Fall back to default tooltip
	const finalContent = custom ?? defaultTooltipGenerator(data, event);
	if (!finalContent) {
		tooltipRef.open = false;
		return;
	}

	// Clear previous content (faster/cleaner than innerHTML = "")
	content.replaceChildren();

	// Render final content
	if (typeof finalContent === "string") {
		content.innerHTML = await sanitizeHtml(finalContent);
	} else {
		content.appendChild(createDOMElementFromVNode(finalContent));
	}

	// Open popover (single place)
	tooltipRef.anchor = target;
	tooltipRef.open = true;
};

const hideChartPopover = (tooltipRef: HTMLHbrPopoverElement) => {
	if (!tooltipRef) {
		console.warn("Tooltip reference is not provided");
		return;
	}
	tooltipRef.open = false;
	const content = tooltipRef.querySelector("[slot=content]") as HTMLDivElement;
	content.innerHTML = "";
};

const hasAssignedLoadingState = (host) => {
	const slot = host.querySelector(
		'slot[name="loading-state"]',
	) as HTMLSlotElement;
	if (slot) {
		const assignedNodes = slot.assignedNodes();
		return assignedNodes.some((node) => node.nodeType === Node.ELEMENT_NODE);
	}
	return false;
};

const hasAssignedEmptyState = (host) => {
	const slot = host.querySelector(
		'slot[name="empty-state"]',
	) as HTMLSlotElement;
	if (slot) {
		const assignedNodes = slot.assignedNodes();
		return assignedNodes.some((node) => node.nodeType === Node.ELEMENT_NODE);
	}
	return false;
};

/**
 * This function hides native empty state ref and shows react rendered ref
 */
const showReactEmptyRef = (emptyNativeRef, emptyRootRef) => {
	if (emptyNativeRef) {
		emptyNativeRef.style.display = "none";
	}
	if (emptyRootRef) {
		emptyRootRef.style.display = "";
	}
};

const hideBothEmptyRefs = (emptyNativeRef, emptyRootRef) => {
	if (emptyNativeRef) {
		emptyNativeRef.style.display = "none";
	}
	if (emptyRootRef) {
		emptyRootRef.style.display = "none";
	}
};

/**
 * This function shows native empty state ref and hides react rendered ref
 */
const showNativeEmptyRef = (emptyNativeRef, emptyRootRef) => {
	if (emptyNativeRef) {
		emptyNativeRef.style.display = "";
	}
	if (emptyRootRef) {
		emptyRootRef.style.display = "none";
	}
};

type IllustrationSize = "large" | "medium" | "small";
type ChartBoardType =
	| "none"
	| "categorical"
	| "categorical-sankey"
	| "bar"
	| "line"
	| "donut"
	| "gauge"
	| "pie";

function computeIllustrationSize(
	width: number,
	type: ChartBoardType,
): IllustrationSize {
	if (
		type === "donut" ||
		type === "gauge" ||
		type === "pie" ||
		type === "categorical-sankey"
	)
		return "medium";
	if (width < 240) return "small";
	if (width < 320) return "medium";
	return "large";
}

function getBarlineEmptyConfigVisibilityOnSize(
	width: number,
	type: ChartBoardType,
) {
	if (type !== "bar" && type !== "line") return false;

	if (width < 240) return false;

	return true;
}

function shouldRenderDefaultEmpty(params: {
	isLoading: boolean;
	isEmpty: boolean;
	type: ChartBoardType;
	hasCustomEmpty: boolean;
}): boolean {
	const { isLoading, isEmpty, type, hasCustomEmpty } = params;
	return !isLoading && isEmpty && !hasCustomEmpty && type !== "none";
}

function makeEmptyRenderKey(type: ChartBoardType, description: string) {
	return `${type}::${description}`;
}

function createBoardController(opts: {
	getEl: () => HTMLElement;

	// state inputs
	getIsLoading: () => boolean;
	getIsEmpty: () => boolean;
	getType: () => ChartBoardType;
	getDescription: () => string;

	// refs readiness
	hasEmptyRefs: () => boolean;

	// side-effects delegated back to component
	updateIllustrationSize: (next: IllustrationSize) => void;
	toggleVisibilityOnBarLineEmpty: (visible: boolean) => void;
	renderDefaultEmptyBg: (w: number, h: number, show: boolean) => void;

	// debounce settings
	debounceMs?: number;
}) {
	const debounceMs = opts.debounceMs ?? 80;

	let lastEmptyRenderKey: string | null = null;

	// RO loop prevention + resize bookkeeping
	let lastMeasuredW = 0;
	let lastMeasuredH = 0;
	let roWriteLock = false;

	let pendingW = 0;
	let pendingH = 0;

	const applyResize = () => {
		if (roWriteLock) return;

		const el = opts.getEl();
		const hasCustomEmpty = hasAssignedEmptyState(el);

		if (
			!shouldRenderDefaultEmpty({
				isLoading: opts.getIsLoading(),
				isEmpty: opts.getIsEmpty(),
				type: opts.getType(),
				hasCustomEmpty,
			})
		) {
			return;
		}

		if (!opts.hasEmptyRefs()) return;

		const w = pendingW;
		const h = pendingH;
		if (w <= 0 || h <= 0) return;

		roWriteLock = true;
		try {
			const barlineEmptyVisibility = getBarlineEmptyConfigVisibilityOnSize(
				w,
				opts.getType(),
			);

			opts.renderDefaultEmptyBg(w, h, barlineEmptyVisibility);
		} finally {
			// release quickly to avoid RO feedback loop
			setTimeout(() => {
				roWriteLock = false;
			}, 0);
		}
	};

	const debouncedApplyResize = debounce(applyResize, debounceMs, {
		trailing: true,
		leading: false,
	});

	const onResize = (width: number, height: number) => {
		if (roWriteLock) return;
		if (width <= 0 || height <= 0) return;

		const w = Math.round(width);
		const h = Math.round(height);

		if (w === lastMeasuredW && h === lastMeasuredH) return;
		lastMeasuredW = w;
		lastMeasuredH = h;

		// update illustration size (cheap)
		const nextSize: IllustrationSize = computeIllustrationSize(
			w,
			opts.getType(),
		);
		opts.updateIllustrationSize(nextSize);

		pendingW = w;
		pendingH = h;

		debouncedApplyResize();
	};

	const renderEmptyIfNeeded = () => {
		const el = opts.getEl();
		const hasCustomEmpty = hasAssignedEmptyState(el);

		if (
			!shouldRenderDefaultEmpty({
				isLoading: opts.getIsLoading(),
				isEmpty: opts.getIsEmpty(),
				type: opts.getType(),
				hasCustomEmpty,
			})
		) {
			lastEmptyRenderKey = null;
			return;
		}

		if (!opts.hasEmptyRefs()) return;

		const rect = el.getBoundingClientRect();
		const w = Math.round(rect.width);
		const h = Math.round(rect.height);
		if (w <= 0 || h <= 0) return;

		const key = makeEmptyRenderKey(opts.getType(), opts.getDescription());
		if (lastEmptyRenderKey === key) return;

		lastEmptyRenderKey = key;

		const barlineEmptyVisibility = getBarlineEmptyConfigVisibilityOnSize(
			w,
			opts.getType(),
		);

		// do an immediate paint (not debounced)
		opts.renderDefaultEmptyBg(w, h, barlineEmptyVisibility);
	};

	const onPropAffectsEmptyChanged = () => {
		lastEmptyRenderKey = null;
		renderEmptyIfNeeded();
	};

	const disconnect = () => {
		debouncedApplyResize.cancel();
		lastEmptyRenderKey = null;
	};

	return {
		onResize,
		renderEmptyIfNeeded,
		onPropAffectsEmptyChanged,
		disconnect,
	};
}

export type { ChartBoardType, IllustrationSize };

export {
	browserDownloadCsv,
	showChartPopover,
	hideChartPopover,
	hasAssignedEmptyState,
	hasAssignedLoadingState,
	showReactEmptyRef,
	showNativeEmptyRef,
	hideBothEmptyRefs,
	createBoardController,
	shouldRenderDefaultEmpty,
	makeEmptyRenderKey,
};
